import json, os, glob
d = os.path.dirname(os.path.abspath(__file__))
meta = json.load(open(f'{d}/scene-meta.json'))
objs = json.load(open(f'{d}/scene-objects.json')) if os.path.exists(f'{d}/scene-objects.json') else {}
for f in glob.glob('/tmp/objs/*.json'):
    n = os.path.basename(f)[:-5]
    if n == 'list':
        continue
    try:
        objs[n] = json.load(open(f))
    except Exception:
        pass
json.dump(objs, open(f'{d}/scene-objects.json', 'w'), separators=(',', ':'))

lines = [
    '// GENERATED by scripts/gen_scene_ts.py from the satellite-derived grids in public/scenes. Do not edit by hand.',
    '/** x, y, length, width (metres), angle (radians) */',
    'export type SceneBoat = [number, number, number, number, number];',
    '/** x, y, length, depth, angle, side, distance to the road (metres, radians) */',
    'export type SceneStand = [number, number, number, number, number, number, number];',
    'export interface SceneMeta { x0: number; y0: number; w: number; h: number; cell: number; ang: number; boats?: SceneBoat[]; stands?: SceneStand[] }',
]
out = {}
for k, v in sorted(meta.items()):
    e = dict(v)
    o = objs.get(k, {})
    if o.get('boats'):
        e['boats'] = o['boats']
    if o.get('stands'):
        e['stands'] = o['stands']
    out[k] = e
lines.append('export const SCENES: Record<string, SceneMeta> = ' + json.dumps(out, separators=(',', ':')) + ';')
lines.append('')
open(f'{d}/../src/game/scenes.generated.ts', 'w').write('\n'.join(lines))
print('wrote', len(meta), 'circuits;', sum(1 for v in out.values() if v.get('stands')), 'with stands;', sum(1 for v in out.values() if v.get('boats')), 'with boats')
